using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluations;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var storage = new DiskBasedReportingStorage(
            Path.Combine(context.TestRunResultsDirectory!, "eval-results"));

        s_reportingConfiguration = new ReportingConfiguration(
            storage,
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                nameof(Chat_ReturnsCoherentResponse));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                nameof(Chat_HandlesFollowUpQuestions));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about photosynthesis."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What role does chlorophyll play in that process?"));
        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_FollowsSystemPromptInstructions()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                nameof(Chat_FollowsSystemPromptInstructions));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that always responds in exactly one sentence."),
            new(ChatRole.User, "Explain what machine learning is."),
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllNumericMetricsPassed();
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://your-resource.openai.azure.com/";
        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT")
            ?? "gpt-4o-mini";

        IChatClient chatClient =
            new Azure.AI.OpenAI.AzureOpenAIClient(new Uri(endpoint),
                new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

